function generateQR(){var e=$("#qr_text").val().trim();if(e){var r=$("#qr_size").val()||"512",t="/api/qr?api_key="+encodeURIComponent(user.api_key)+"&size="+encodeURIComponent(r)+"&text="+encodeURIComponent(e);$("#qr_image").attr("src",t),$("#qr_download").attr("href",t),$("#qr_empty").hide(),$("#qr_result").show()}else errorFlash("Please enter a URL or text")}$(document).ready((function(){$("#qr_generate").click(generateQR),$("#qr_text").keypress((function(e){13===e.which&&generateQR()}))}));